"""Structured product specification. Product decisions, not copied vendor UI."""
SCREENS=[]
def screen(id,module,title,kind,role,goal,fields,actions,exceptions,sources=''):
    SCREENS.append(dict(id=id,module=module,title=title,kind=kind,role=role,goal=goal,
        fields=[dict(label=p.split('~')[0],type=p.split('~')[1],rule=p.split('~')[2]) for p in fields.split(';') if p],
        actions=[dict(label=p.split('~')[0],target=p.split('~')[1],rule=p.split('~')[2]) for p in actions.split(';') if p],
        exceptions=exceptions.split(';'),sources=sources.split(',')))

